interaction.contextCode:
If(
    Connection.Connected,
    Patch(
        Contacts,
        Defaults(Contacts),
        {
            'First Name': DataCardValue_FirstName.Text,
            'Last Name': DataCardValue_LastName.Text
        }
    );
    Navigate(ConfirmationScreen, ScreenTransition.Fade),
    ClearCollect(
        LocalRecord,
        {
            'First Name': DataCardValue_FirstName.Text,
            'Last Name': DataCardValue.Text
        }
    );
    SaveData(LocalRecord, "LocalRecord");
    Navigate(PendingScreen, ScreenTransition.Fade)
)
